// Drift guard and equivalence proof for site/procurement_legal_projection.mjs — the
// browser-safe projection of the PPB 3-08 policy registry and the procurement legal
// register that site modules read.
//
// The projection is generated by tools/build_procurement_legal_projection.mjs. This suite
// proves the committed file equals a fresh build, that its bands mirror the policy registry,
// that its participation and ceiling lookups equal the register's effectFor at every date
// breakpoint and its neighbours, that the consuming modules hold no hand-copied number, and
// that the new browser-safe modules carry no node builtins into the Pages bundle graph.

import { readFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { test } from "node:test";
import assert from "node:assert/strict";

import * as legal from "../ontology/procurement_legal_register.mjs";
import { loadOntologyRegistry } from "../ontology/load.mjs";
import {
  buildProcurementLegalProjection,
  renderProcurementLegalProjectionModule,
} from "../tools/build_procurement_legal_projection.mjs";
import {
  PROCUREMENT_COVERAGE_AMOUNT_BANDS,
  PROCUREMENT_COVERAGE_POLICY_EFFECTIVE_FROM,
} from "../site/procurement_coverage_labels.mjs";
import {
  participationRequirement,
  mwbeSmallPurchaseCeilingOn,
} from "../site/procurement_legal_category.mjs";

const REPO_ROOT = fileURLToPath(new URL("..", import.meta.url));
const register = legal.loadProcurementLegalRegister();
const policyRegistry = loadOntologyRegistry().procurement_policy_registry;
const sources = Object.fromEntries(
  Object.keys(register.sources.files).map((f) => [
    f,
    readFileSync(join(REPO_ROOT, register.sources.root, f), "utf8"),
  ]),
);
const ctx = { register, policyRegistry };
const latest = new Map();
for (const e of register.entries) {
  if (!latest.has(e.id) || latest.get(e.id).record_version < e.record_version) latest.set(e.id, e);
}
const build = () => buildProcurementLegalProjection({ register, policyRegistry, legal, sources });
const ALL_CATEGORIES = ["goods", "standard_services", "professional_services", "construction", "human_services"];

test("A8: the committed projection equals a fresh build (drift guard)", () => {
  const committed = readFileSync(join(REPO_ROOT, "site/procurement_legal_projection.mjs"), "utf8");
  assert.equal(
    committed,
    renderProcurementLegalProjectionModule(build()),
    "site/procurement_legal_projection.mjs is stale; run node tools/build_procurement_legal_projection.mjs --write",
  );
});

test("A8: projection bands deep-equal the policy registry and coverage reads them", () => {
  const built = build();
  for (const family of policyRegistry.method_families) {
    if (!family.applicability.amount_bands.length) continue;
    const projected = built.policy.families[family.id];
    assert.equal(projected.effective_from, family.effective_from);
    for (const band of family.applicability.amount_bands) {
      assert.deepEqual(projected.bands[band.procurement_category], {
        min: band.minimum,
        minInclusive: band.minimum_inclusive,
        max: band.maximum,
        maxInclusive: band.maximum_inclusive,
      });
    }
    for (const stage of family.stages) {
      assert.equal(projected.stages[stage.id].publication_obligation, stage.publication_obligation);
    }
  }
  assert.deepEqual(PROCUREMENT_COVERAGE_AMOUNT_BANDS.mwbe_small_purchase.construction, {
    min: 35000,
    minInclusive: false,
    max: 1500000,
    maxInclusive: true,
  });
  assert.equal(PROCUREMENT_COVERAGE_POLICY_EFFECTIVE_FROM, policyRegistry.source.effective_from);
});

test("A8: an uncategorised record's legal candidate set is every category its family can legally take", () => {
  const built = build();
  assert.deepEqual(built.policy.families.ordinary_micropurchase.legal_categories, ALL_CATEGORIES);
  assert.equal(built.policy.families.ordinary_micropurchase.legal_categories_basis, "9 RCNY 3-08(c)(1)(ii)");
  assert.deepEqual(built.policy.families.ordinary_5_plus_10.legal_categories, ALL_CATEGORIES);
  assert.equal(built.policy.families.ordinary_5_plus_10.legal_categories_basis, "9 RCNY 3-08(c)(1)(iii)");
  assert.deepEqual(
    built.policy.families.mwbe_small_purchase.legal_categories,
    ALL_CATEGORIES.filter((c) => c !== "human_services"),
  );
  assert.equal(built.policy.families.mwbe_small_purchase.legal_categories_basis, "9 RCNY 3-08(c)(1)(iv)");
  // The basis phrases are checked against the retained text; a source without them fails the build.
  assert.throws(
    () => buildProcurementLegalProjection({
      register,
      policyRegistry,
      legal: { ...legal, validateLegalRegister: () => true },
      sources: { ...sources, "ppb-3-08.md": "## § 3-08\n" },
    }),
    /phrase not in ppb-3-08\.md/,
  );
});

test("A2/A8: every floor's day count comes from its register rule", () => {
  const built = build();
  for (const [kind, floor] of Object.entries(built.floors)) {
    const entry = latest.get(floor.rule_id);
    assert.equal(
      floor.days,
      entry.effect.minimum_response_calendar_days ?? entry.effect.minimum_response_business_days,
      kind,
    );
  }
});

test("A8: participation and ceiling lookups equal effectFor at every breakpoint and its neighbours", () => {
  const built = build();
  const dates = new Set(["2020-01-01", "2024-06-30", "2026-11-11"]);
  for (const rows of Object.values(built.participation.table)) {
    for (const { from } of rows) {
      if (from === "0001-01-01") continue;
      const d = new Date(`${from}T00:00:00Z`);
      for (const delta of [-1, 0, 1]) {
        dates.add(new Date(d.getTime() + delta * 86400000).toISOString().slice(0, 10));
      }
    }
  }
  for (const category of [...ALL_CATEGORIES, null]) {
    for (const form of [null, "for_profit", "not_for_profit"]) {
      for (const date of dates) {
        const facts = {
          occurred_on: date,
          ...(category ? { procurement_category: category } : {}),
          ...(form ? { awardee_legal_form: form } : {}),
        };
        const live = legal.effectFor(facts, "mwbe_participation_requirement", ctx);
        const looked = participationRequirement({
          candidates: category ? [category] : [],
          awardee_legal_form: form,
          occurred_on: date,
        });
        if (live.value === "not_applicable") {
          assert.equal(looked.value, "not_applicable", `${category}/${form}/${date}`);
          assert.deepEqual([...looked.rule_ids], [...live.rule_ids].sort());
        } else {
          assert.notEqual(looked.value, "not_applicable", `${category}/${form}/${date}`);
        }
      }
    }
  }
  for (const date of ["2022-10-05", "2022-10-06", "2023-07-17", "2023-12-07", "2023-12-08", "2026-11-11"]) {
    const live = legal.effectFor({}, "mwbe_small_purchase_max_usd", { ...ctx, asOf: date });
    const looked = mwbeSmallPurchaseCeilingOn(date);
    assert.equal(looked?.max_usd ?? "unknown", live.value, date);
  }
});

test("A6: the consuming modules hold no hand-copied dollar band, policy date or floor day count", () => {
  for (const name of [
    "procurement_coverage_labels.mjs",
    "solicitation_procurement_method.mjs",
    "mwbe_goal_surface.mjs",
    "mwbe_requirement_state.mjs",
    "procurement_legal_category.mjs",
  ]) {
    const text = readFileSync(join(REPO_ROOT, "site", name), "utf8");
    assert.doesNotMatch(text, /\b(20_?000|35_?000|100_?000|1_?000_?000|1_?500_?000)\b/, `${name} copies a dollar band`);
    assert.doesNotMatch(text, /"2023-0[0-9]-[0-9]{2}"/, `${name} copies a policy date`);
    assert.doesNotMatch(text, /days:\s*(3|15|20|22|27)\b/, `${name} copies a floor`);
  }
});

test("the Pages bundle graph stays free of node builtins with the new site modules in it", async () => {
  const { findPagesBundleNodeBuiltins } = await import(
    pathToFileURL(join(REPO_ROOT, "tools/check_pages_bundle_node_builtins.mjs")).href
  );
  const result = await findPagesBundleNodeBuiltins();
  assert.deepEqual(result.violations, []);
  for (const name of ["procurement_legal_projection.mjs", "procurement_legal_category.mjs", "mwbe_requirement_state.mjs"]) {
    assert.ok(result.files.some((f) => f.endsWith(`/site/${name}`)), `${name} is in the Pages bundle graph`);
  }
});
